    "Choose a file": "Scegli un file",
    "Office files stay on your device. Layout, formulas, charts, animations, fonts and page breaks may change. Office to PDF opens your browser’s print dialog. Use a computer for large files.": "I file Office rimangono sul tuo dispositivo. Layout, formule, grafici, animazioni, caratteri e interruzioni di pagina potrebbero subire variazioni. La funzione \"Da Office a PDF\" apre la finestra di dialogo di stampa del browser. Usa un computer per i file di grandi dimensioni.",
    "PDF to Excel estimates rows from selectable text; it does not recreate formulas or tables. PDF to PowerPoint makes image-only slides. Scanned PDFs need OCR first.": "PDF to Excel ricava le righe dal testo selezionabile; non ricrea formule o tabelle. PDF to PowerPoint crea diapositive composte solo da immagini. I PDF scansionati richiedono prima l'OCR.",
