    "JPG, PNG, WebP, HEIC/HEIF, AVIF, BMP, GIF/APNG, SVG or ICO. Animated files export their first frame. Metadata is not copied.": "JPG, PNG, WebP, HEIC/HEIF, AVIF, BMP, GIF/APNG, SVG o ICO. Dei file animati viene esportato solo il primo fotogramma. I metadati non vengono copiati.",
    "Transparent areas become white. Animated images use only their first frame.": "Le aree trasparenti diventano bianche. Le immagini animate utilizzano solo il primo fotogramma.",
    "JPG, PNG, WebP, HEIC/HEIF, AVIF, BMP, GIF/APNG, SVG and ICO. Animated files export only their first frame. Output up to 40 megapixels.": "JPG, PNG, WebP, HEIC/HEIF, AVIF, BMP, GIF/APNG, SVG e ICO. Dei file animati viene esportato solo il primo fotogramma. Output fino a 40 megapixel.",
    "Convert common image formats to JPG, PNG or WebP on your device. Up to 20 files.": "Converti i formati di immagine comuni in JPG, PNG o WebP direttamente sul tuo dispositivo. Fino a 20 file.",
    "Add up to 20 images. No fixed file-size cap; 20 megapixels per image. Large batches depend on your device memory.": "Aggiungi fino a 20 immagini. Nessun limite fisso alla dimensione del file; 20 megapixel per immagine. L'elaborazione di grandi lotti dipende dalla memoria del dispositivo.",
    "Images converted. Animated files become a still frame; metadata is not copied.": "Immagini convertite. I file animati diventano un fotogramma statico; i metadati non vengono copiati.",
    "Some files were skipped. Use a supported image format within the on-page limits.": "Alcuni file sono stati ignorati. Utilizza un formato immagine supportato e rispetta i limiti indicati nella pagina.",
    "This image could not be decoded by your browser. Try another file or browser.": "Impossibile decodificare l'immagine con il browser in uso. Prova un altro file o un altro browser.",
    "Choose a supported image format.": "Scegli un formato immagine supportato.",
    "The browser does not support the selected output format.": "Il browser non supporta il formato di output selezionato.",
    "Up to 20 images · 20 megapixels per image · no fixed file-size cap. Large batches depend on your device memory.": "Fino a 20 immagini · 20 megapixel per immagine · nessun limite fisso alla dimensione del file. L'elaborazione di grandi lotti dipende dalla memoria del dispositivo.",
    "Choose up to 20 images.": "Scegli fino a 20 immagini.",
    "AVIF and some HEIC files may depend on browser support.": "I file AVIF e alcuni HEIC potrebbero dipendere dal supporto del browser.",
    "AVIF and some HEIC inputs depend on browser support. Animated GIF, APNG and WebP files become a still image. SVG is rasterized, not converted into an editable vector. Metadata is not copied.": "Gli input AVIF e alcuni HEIC dipendono dal supporto del browser. I file animati GIF, APNG e WebP vengono trasformati in immagini statiche. Il formato SVG viene rasterizzato, non convertito in un vettore modificabile. I metadati non vengono copiati.",
    "Multi-page TIFF uses only its first page. Some TIFF compression variants may not decode.": "Per i file TIFF multipagina viene utilizzata solo la prima pagina. Alcune varianti di compressione TIFF potrebbero non essere decodificate.",
    "Choose a DOCX, XLSX or PPTX file": "Scegli un file DOCX, XLSX o PPTX",
    "Files stay on your device. Limits: 100 MB input, 200 MB expanded data and 5,000 package parts.": "I file rimangono sul dispositivo. Limiti: 100 input MB, 200 dati espansi MB e 5.000 parti del pacchetto.",
    "This safely recompresses the Office package without rewriting its contents. Embedded photos are not recompressed, so the result may not be smaller. Signed, encrypted, macro-enabled and older Office files are not supported. Keep your original.": "Questa operazione ricomprime in modo sicuro il pacchetto Office senza riscriverne il contenuto. Le foto incorporate non vengono ricompresse, pertanto il risultato finale potrebbe non essere di dimensioni ridotte. I file Office firmati, crittografati, con macro o in formati meno recenti non sono supportati. Conserva il file originale.",
    "Try to reduce file size": "Prova a ridurre le dimensioni del file",
    "Processing runs locally in this browser. No upload.": "L'elaborazione avviene localmente nel browser. Nessun caricamento.",
    "Recompressing the Office package on your device…": "Ricompressione del pacchetto Office sul dispositivo in corso...",
    "This package is already compact. No smaller download was created.": "Il pacchetto è già compatto. Non è stato creato alcun file di dimensioni ridotte.",
    "A smaller copy is ready. Compare it and keep your original.": "Una copia di dimensioni ridotte è pronta. Confrontalo e conserva l'originale.",
    "The file could not be safely recompressed. Your original has not changed.": "Impossibile ricomprimere il file in modo sicuro. L'originale non è stato modificato.",
    "Processing canceled. Your original file is unchanged.": "Elaborazione annullata. Il file originale è rimasto invariato.",
    "Choose a modern DOCX, XLSX or PPTX file.": "Scegli un file moderno DOCX, XLSX o PPTX.",
    "This file is larger than the 100 MB local processing limit.": "Questo file supera il limite di elaborazione locale di 100 MB.",
    "The expanded package exceeds the 200 MB local processing limit.": "Il pacchetto espanso supera il limite di elaborazione locale di 200 MB.",
    "Encrypted Office packages are not supported.": "I pacchetti Office crittografati non sono supportati.",
    "Signed or macro-enabled Office files are not supported, to avoid invalidating signatures or macros.": "I file Office firmati o con macro abilitate non sono supportati, per evitare di invalidare firme o macro.",
    "The selected file is not a valid modern Office document of that type.": "Il file selezionato non è un documento Office moderno valido di quel tipo.",
