    "For long or high-resolution media, a desktop or laptop is recommended. Keep this tab open; speed, memory and battery depend on your device.": "Per file multimediali lunghi o ad alta risoluzione, si consiglia l'uso di un computer desktop o portatile. Mantieni aperta questa scheda; velocità, memoria e batteria dipendono dal tuo dispositivo.",
