    "First use downloads about 58 MB of model and local engine. Your recording is not uploaded; the browser may download them again if its cache is cleared.": "Al primo utilizzo vengono scaricati circa 58 MB relativi al modello e al motore locale. La registrazione non viene caricata; il browser potrebbe scaricarla nuovamente se la cache viene svuotata.",
