    "The browser creates the PDF. Paper size, margins and headers are set in the print dialog.": "Il browser crea il PDF. Il formato carta, i margini e le intestazioni si impostano nella finestra di stampa.",
    "For safety, scripts, styles, images, links, forms and external content are removed. This tool prints simple text and tables; it does not convert a website URL.": "Per sicurezza, script, stili, immagini, collegamenti, moduli e contenuti esterni vengono rimossi. Questo strumento stampa testo semplice e tabelle; non converte l'URL di un sito web.",
    "HTML content is limited to 250,000 characters. Website URLs are not fetched.": "Il contenuto HTML è limitato a 250.000 caratteri. Gli URL dei siti web non vengono recuperati.",
    "Choose a PDF to convert to PDF/A": "Scegli un PDF da convertire in PDF/A",
    "PDF/A-1b makes a flattened image copy of every page. Text is not searchable or selectable. Forms, links, existing signatures, metadata and accessibility structure are not retained. Keep your original.": "Il formato PDF/A-1b crea una copia immagine \"appiattita\" (senza livelli) di ogni pagina. Il testo non è ricercabile né selezionabile. Moduli, collegamenti, firme esistenti, metadati e struttura di accessibilità non vengono mantenuti. Conserva l'originale.",
    "This is a visual archival copy, not an accessibility or electronic-signature copy. The browser does not run veraPDF on each file. Validate the download before relying on archival compliance.": "Si tratta di una copia visiva per l'archiviazione, non di una copia destinata all'accessibilità o alla firma elettronica. Il browser non esegue veraPDF su ogni file. Convalida il download prima di basarti su di esso per la conformità dell'archiviazione.",
    "Output resolution": "Risoluzione di output",
