    "This PDF could not be converted to a PDF/A copy. The original file is unchanged.": "Non è stato possibile convertire questo PDF in una copia PDF/A. Il file originale rimane invariato.",
    "This PDF is processed on your device and is not uploaded. A computer is recommended for this memory-intensive conversion.": "Questo PDF viene elaborato sul tuo dispositivo e non viene caricato online. Si consiglia l'uso di un computer per questa conversione che richiede molta memoria.",
    "Visual edits flatten modified pages; searchable text on them is lost. Limit: 50 MB, 100 pages, 40 MP. A computer is recommended.": "Le modifiche visive appiattiscono le pagine modificate; il testo ricercabile in esse contenuto viene perso. Limiti: 50 MB, 100 pagine, 40 MP. Si consiglia l'uso di un computer.",
    "Edit text or image": "Modifica testo o immagine",
